import{_ as t,o as d,c as r,e as a}from"./app-26157173.js";const i={},l=a('<h1 id="海外建站指南" tabindex="-1"><a class="header-anchor" href="#海外建站指南" aria-hidden="true">#</a> 海外建站指南</h1><blockquote><p>覆盖：建站流程、平台选型、优缺点对比 整理时间：2026-10-29 适用对象：外贸工厂、跨境卖家、B2B 询盘型与 B2C 零售型企业</p></blockquote><hr><h2 id="一、建站前先想清楚的三件事" tabindex="-1"><a class="header-anchor" href="#一、建站前先想清楚的三件事" aria-hidden="true">#</a> 一、建站前先想清楚的三件事</h2><h3 id="_1-站点定位-决定一切选型" tabindex="-1"><a class="header-anchor" href="#_1-站点定位-决定一切选型" aria-hidden="true">#</a> 1. 站点定位（决定一切选型）</h3><table><thead><tr><th>类型</th><th>目标</th><th>核心指标</th><th>典型代表</th></tr></thead><tbody><tr><td><strong>B2B 询盘站</strong></td><td>拿到客户邮件/WhatsApp 询盘</td><td>询盘转化率、SEO 排名</td><td>某外贸工厂官网（SaaS 搭建）</td></tr><tr><td><strong>B2C 零售独立站</strong></td><td>直接在线成交收钱</td><td>转化率、客单价、复购</td><td>SHEIN 独立站、Anker 官网</td></tr><tr><td><strong>品牌官网</strong></td><td>树立品牌形象、承接流量</td><td>设计感、品牌信任度</td><td>大卖的品牌门户</td></tr></tbody></table><p><strong>判断方法</strong>：客户是在网站上直接付款（B2C），还是看完要联系业务员谈（B2B）？两者功能完全不同，选型前必须定死。</p><h3 id="_2-预算" tabindex="-1"><a class="header-anchor" href="#_2-预算" aria-hidden="true">#</a> 2. 预算</h3><ul><li>每年愿意花 500~2500 元（低成本托管）</li><li>还是 3000~1 万元（国内主流 SaaS）</li><li>还是有技术团队、想完全自主（开源自建）</li></ul><h3 id="_3-有没有技术能力-谁来维护" tabindex="-1"><a class="header-anchor" href="#_3-有没有技术能力-谁来维护" aria-hidden="true">#</a> 3. 有没有技术能力 / 谁来维护</h3><p>没有维护人手，就闭眼选 SaaS；有技术团队且要深度定制，考虑开源。</p><hr><h2 id="二、选型-四大阵营-主流平台" tabindex="-1"><a class="header-anchor" href="#二、选型-四大阵营-主流平台" aria-hidden="true">#</a> 二、选型：四大阵营 + 主流平台</h2><h3 id="阵营-1-国际-saas-shopify-为代表" tabindex="-1"><a class="header-anchor" href="#阵营-1-国际-saas-shopify-为代表" aria-hidden="true">#</a> 阵营 1：国际 SaaS（Shopify 为代表）</h3><ul><li><strong>技术栈</strong>：Ruby on Rails + Liquid 模板，全球工程成熟度天花板</li><li><strong>价格</strong>：年付基础版约 $29/月，高阶 $299/月，交易佣金 2%（用 Shopify Payments 可免）</li><li><strong>优点</strong>： <ul><li>生态最强：上万款应用、全球主题市场、支付/物流/POS 全打通</li><li>稳定性和性能不用操心</li><li>出海团队几乎人人会用，资料最多</li></ul></li><li><strong>缺点</strong>： <ul><li>Shopify Payments 需要海外主体，中国卖家收款要绕</li><li>国内访问后台慢，官方中文支持弱</li><li>应用费用叠加，长期成本不低</li><li>数据在平台，被封号即归零</li></ul></li><li><strong>适合</strong>：有出海团队、做 DTC 品牌零售、预算充足的卖家</li></ul><h3 id="阵营-2-国产出海-saas" tabindex="-1"><a class="header-anchor" href="#阵营-2-国产出海-saas" aria-hidden="true">#</a> 阵营 2：国产出海 SaaS</h3><h4 id="shoplazza-店匠" tabindex="-1"><a class="header-anchor" href="#shoplazza-店匠" aria-hidden="true">#</a> Shoplazza 店匠</h4><ul><li>深圳团队，中国出海卖家用得最多的国产 SaaS，定位国际化</li><li>月付 $28~$218 + 佣金 2%~0.2%，年付约八折</li><li>模板设计感强，全球支付覆盖广（196 种本地支付、254 个国家/地区），中东等新兴市场本地化深，已上线 AI 建站 Agent</li><li>短板：月费高于国内同行，深度定制（复杂 B2B、多仓）支持不足</li></ul><h4 id="ueeshop" tabindex="-1"><a class="header-anchor" href="#ueeshop" aria-hidden="true">#</a> Ueeshop</h4><ul><li>广州联雅出品，做了近二十年的老牌，主打 B2B 外贸官网</li><li>年付制：标准版约 4800 元/年起，独立部署 6.8 万起，佣金 0.2%~0.5%</li><li>B2B 询盘功能全、SEO 基建扎实、中文一对一客服响应快</li><li>短板：插件生态小、模板偏保守、设计自由度低</li></ul><h4 id="shopagg-新兴小平台" tabindex="-1"><a class="header-anchor" href="#shopagg-新兴小平台" aria-hidden="true">#</a> ShopAgg（新兴小平台）</h4><ul><li>一站式打包：建站 + 域名 + 企业邮箱 + 在线客服 + 自建访客统计</li><li>PHP 轻量技术栈（PHP 模板 + Tailwind，Nginx/Caddy 代理），每站独立环境、每日自动备份</li><li>¥99~199/月，无交易佣金，四家门槛最低</li><li>短板：生态几乎为零、功能深度有限、平台自身稳定性待验证</li></ul><h3 id="阵营-3-开源自建-wordpress-woocommerce-为代表" tabindex="-1"><a class="header-anchor" href="#阵营-3-开源自建-wordpress-woocommerce-为代表" aria-hidden="true">#</a> 阵营 3：开源自建（WordPress + WooCommerce 为代表）</h3><ul><li>软件完全免费开源，自己买服务器（VPS 约 $5~30/月）+ 域名（$15/年）+ SSL（免费 Let&#39;s Encrypt）</li><li>优点： <ul><li><strong>数据 100% 自有</strong>，随时迁移，无平台倒闭/封号风险</li><li>无交易佣金，长期成本最低</li><li>无限自由：PHP 生态 6 万+ 插件，B2B 阶梯价、订阅制、会员体系都能做</li><li>SEO 控制力最强（可精细化到每个 URL、Schema、站内结构）</li></ul></li><li>缺点： <ul><li><strong>安全靠自己</strong>：插件漏洞、不更新被黑是最大软肋，需要持续维护</li><li>上手有门槛：环境部署、主题调试、性能优化都要人管</li><li>隐性成本易低估：外包改功能、修站的钱几年下来未必比 SaaS 便宜</li></ul></li><li><strong>适合</strong>：B2B 询盘站（无在线支付、重内容+表单）、有技术能力、要长期经营、怕被平台卡脖子的团队</li></ul><h3 id="阵营-4-纯静态-手写-进阶可选" tabindex="-1"><a class="header-anchor" href="#阵营-4-纯静态-手写-进阶可选" aria-hidden="true">#</a> 阵营 4：纯静态/手写（进阶可选）</h3><ul><li>用 HTML/Astro/Next.js 手写官网，托管到 Cloudflare Pages / Vercel（免费额度足够 B2B 站用）</li><li>成本趋近于零、性能极好、无任何依赖</li><li>缺点：需要开发能力，内容更新要改代码或接 Headless CMS</li><li>适合有开发团队的公司做品牌官网</li></ul><h3 id="选型速查表" tabindex="-1"><a class="header-anchor" href="#选型速查表" aria-hidden="true">#</a> 选型速查表</h3><table><thead><tr><th></th><th>Shopify</th><th>Shoplazza</th><th>Ueeshop</th><th>ShopAgg</th><th>WordPress 自建</th></tr></thead><tbody><tr><td>背景</td><td>加拿大，全球龙头</td><td>深圳，出海头部</td><td>广州，老牌外贸</td><td>新兴小平台</td><td>开源社区</td></tr><tr><td>定位</td><td>全球 DTC</td><td>国际化 DTC</td><td>B2B 外贸官网</td><td>低成本一站式</td><td>完全自主</td></tr><tr><td>计费</td><td>月付+2% 佣金</td><td>月付+2%~0.2%</td><td>年付+低佣金</td><td>¥99/月无佣金</td><td>无平台费</td></tr><tr><td>生态</td><td>最强</td><td>中等</td><td>较小</td><td>几乎没有</td><td>最大（插件）</td></tr><tr><td>中文支持</td><td>弱</td><td>好</td><td>很好</td><td>好</td><td>社区/自行解决</td></tr><tr><td>数据归属</td><td>平台</td><td>平台</td><td>平台</td><td>平台</td><td>完全自有</td></tr><tr><td>技术门槛</td><td>低</td><td>低</td><td>低</td><td>低</td><td>中高</td></tr><tr><td>适合</td><td>出海 DTC 团队</td><td>品牌化中国卖家</td><td>工厂/贸易 B2B</td><td>预算有限小工厂</td><td>有技术、求长期</td></tr></tbody></table><p><strong>一句话决策</strong>：</p><ul><li>想直接卖货给海外消费者 → Shoplazza（中国卖家）/ Shopify（有海外主体）</li><li>拿询盘做批发生意 → Ueeshop / ShopAgg / WordPress 自建</li><li>预算极低先跑起来 → ShopAgg 或 WordPress</li><li>不想被任何平台绑定 → WordPress / 静态站</li></ul><hr><h2 id="三、海外建站全流程-以-b2b-询盘站为例" tabindex="-1"><a class="header-anchor" href="#三、海外建站全流程-以-b2b-询盘站为例" aria-hidden="true">#</a> 三、海外建站全流程（以 B2B 询盘站为例）</h2><h3 id="阶段-1-准备期-1-3-天" tabindex="-1"><a class="header-anchor" href="#阶段-1-准备期-1-3-天" aria-hidden="true">#</a> 阶段 1：准备期（1~3 天）</h3><ol><li><strong>确定定位与受众</strong>：B2B 还是 B2C？目标市场（欧美/中东/东南亚）？</li><li><strong>注册域名</strong>：首选 .com，简短、含品牌词或核心产品词（如 your-product-supplier.com）；在 Namecheap/Cloudflare/平台方注册</li><li><strong>规划内容架构</strong>：首页、产品列表、产品详情、About Us、Factory/案例、Blog、Contact——B2B 站这六类页面是标配</li></ol><h3 id="阶段-2-搭建期-3-7-天" tabindex="-1"><a class="header-anchor" href="#阶段-2-搭建期-3-7-天" aria-hidden="true">#</a> 阶段 2：搭建期（3~7 天）</h3><ol start="4"><li><strong>选定平台</strong>，按上面决策表选</li><li><strong>选模板/主题</strong>：B2B 走工业风简洁风，B2C 重视觉转化</li><li><strong>录入核心内容</strong>： <ul><li>产品页：高清图 + 英文详情（B2C）或参数/起订量/定制能力（B2B）</li><li>信任要素：工厂实拍、认证证书（FDA/Halal/BRC 等）、合作案例</li></ul></li><li><strong>配置获客入口</strong>： <ul><li>B2B：询盘表单 + WhatsApp 悬浮按钮 + 在线客服</li><li>B2C：支付通道（Stripe/PayPal/本地支付）+ 物流方案</li></ul></li></ol><h3 id="阶段-3-seo-基建-上线前必做" tabindex="-1"><a class="header-anchor" href="#阶段-3-seo-基建-上线前必做" aria-hidden="true">#</a> 阶段 3：SEO 基建（上线前必做）</h3><ol start="8"><li><strong>技术 SEO</strong>：自定义 URL、Meta/OG 标签、canonical、robots.txt、sitemap.xml、移动端适配</li><li><strong>结构化数据</strong>：JSON-LD（Organization / Product / FAQ），Google 富摘要靠它</li><li><strong>提交 Google Search Console</strong>，申请收录</li><li><strong>速度优化</strong>：图片压缩、WebP 格式、懒加载（海外用户对加载速度极敏感）</li></ol><h3 id="阶段-4-上线与合规" tabindex="-1"><a class="header-anchor" href="#阶段-4-上线与合规" aria-hidden="true">#</a> 阶段 4：上线与合规</h3><ol start="12"><li><strong>HTTPS 强制</strong>（现代浏览器的底线）</li><li><strong>隐私合规</strong>：GDPR 隐私政策页 + Cookie 同意横幅（面向欧洲必须做）</li><li><strong>备案/主体</strong>：服务器在海外则无需国内备案；注意目标市场对食品/电子等品类的合规要求</li></ol><h3 id="阶段-5-获客运营-持续" tabindex="-1"><a class="header-anchor" href="#阶段-5-获客运营-持续" aria-hidden="true">#</a> 阶段 5：获客运营（持续）</h3><ol start="15"><li><strong>内容营销</strong>：Blog 定期更新行业内容（如 &quot;How to source from Chinese factories&quot;），这是 B2B 站自然流量的主要来源</li><li><strong>数据分析</strong>：Google Analytics 4 或平台自带统计，看来源、热门页、询盘转化路径</li><li><strong>再营销</strong>：Facebook/Google Pixel 埋点，广告再触达</li><li><strong>持续迭代</strong>：根据搜索词和询盘数据优化页面与关键词</li></ol><hr><h2 id="四、优缺点总结-saas-vs-开源-一图看懂" tabindex="-1"><a class="header-anchor" href="#四、优缺点总结-saas-vs-开源-一图看懂" aria-hidden="true">#</a> 四、优缺点总结（SaaS vs 开源 一图看懂）</h2><table><thead><tr><th>维度</th><th>SaaS 建站</th><th>WordPress/WooCommerce 自建</th></tr></thead><tbody><tr><td>前期成本</td><td>几乎为零</td><td>软件 0 元，服务器+域名约 $100/年起</td></tr><tr><td>长期成本</td><td>月费+佣金持续交</td><td>无佣金，主要是运维人力</td></tr><tr><td>上手难度</td><td>一两天上线</td><td>有门槛，需技术或外包</td></tr><tr><td>维护责任</td><td>平台全包</td><td>全是自己的事</td></tr><tr><td>自由度</td><td>受限模板和 API</td><td>无限定制</td></tr><tr><td>数据所有权</td><td>在平台手里</td><td>完全自有</td></tr><tr><td>安全</td><td>平台负责</td><td>自己负责（最大风险点）</td></tr><tr><td>平台风险</td><td>停运/封号/涨价（某平台 2021 年关停即前车之鉴）</td><td>无</td></tr></tbody></table><p><strong>核心记忆点</strong>：SaaS 是租房——省心但房东说了算；WordPress 是盖房——自由但一切自己扛。</p><hr><h2 id="五、成本预算参考-第一年" tabindex="-1"><a class="header-anchor" href="#五、成本预算参考-第一年" aria-hidden="true">#</a> 五、成本预算参考（第一年）</h2><table><thead><tr><th>方案</th><th>固定支出</th><th>交易成本</th><th>适合</th></tr></thead><tbody><tr><td>ShopAgg 入门版</td><td>¥1188/年</td><td>无佣金</td><td>预算极低的 B2B</td></tr><tr><td>Ueeshop 标准版</td><td>~¥4800/年</td><td>0.5% 左右</td><td>正经 B2B 询盘运营</td></tr><tr><td>Shoplazza 基础版</td><td>~$270/年(年付)</td><td>2%</td><td>DTC 起步</td></tr><tr><td>Shopify 基础版</td><td>~$348/年(年付)</td><td>2%</td><td>DTC 正规军</td></tr><tr><td>WordPress 自建</td><td>$100~300/年</td><td>无</td><td>有技术能力的 B2B/长期玩家</td></tr><tr><td>静态站托管</td><td>¥0~100/年</td><td>无</td><td>有开发团队的品牌官网</td></tr></tbody></table><blockquote><p>提示：以上为 2026 年公开报价，选型前以官网实时价格为准。</p></blockquote><hr><h2 id="六、常见踩坑提醒" tabindex="-1"><a class="header-anchor" href="#六、常见踩坑提醒" aria-hidden="true">#</a> 六、常见踩坑提醒</h2><ol><li><strong>先选平台再定定位</strong> → 本末倒置，返工成本极高</li><li><strong>忽视移动端</strong> → 海外移动流量占比 60%+，模板必须响应式</li><li><strong>B2B 站照抄 B2C 模板</strong> → 放购物车没有意义，询盘入口才是生命线</li><li><strong>不做 SEO 基建就投广告</strong> → 广告停了流量归零，自然流量才是资产</li><li><strong>忽略隐私合规</strong> → 欧洲 GDPR 罚款是真实风险</li><li><strong>图片直接上传原图</strong> → 加载慢 1 秒，转化率掉 7%</li><li><strong>把宝押在单一平台</strong> → 重要内容（产品数据、客户邮件列表）自己留备份</li></ol><hr><p><em>本文档基于 2026-10 对各平台官网、报价页及若干真实站点的实测调研整理。</em></p>',55),e=[l];function o(h,s){return d(),r("div",null,e)}const g=t(i,[["render",o],["__file","海外建站指南.html.vue"]]);export{g as default};
